<template>
  <div class="module-page"><div class="page-header-row"><div><span class="eyebrow">যাতায়াত ব্যবস্থাপনা</span><h1>পরিবহন রুট</h1><p>মাদ্রাসার রুট, স্টপেজ, ভাড়া ও বাস পরিচালনা করুন</p></div><button class="btn btn-primary" @click="showForm=!showForm"><icon name="plus" /> নতুন রুট</button></div><div class="toolbar card"><div class="search-box"><icon name="search" /><input v-model="search" placeholder="রুট খুঁজুন..." @keyup.enter="load" /></div><button class="btn btn-outline btn-sm" @click="load"><icon name="refresh" /> রিফ্রেশ</button></div><form v-if="showForm" class="create-panel card" @submit.prevent="createRoute"><div class="form-heading"><h2>নতুন পরিবহন রুট</h2><button type="button" class="close-btn" @click="showForm=false">×</button></div><div v-if="error" class="alert alert-error">{{ error }}</div><div class="form-grid"><div class="form-group wide"><label>রুটের নাম *</label><input v-model="form.route_name_bn" class="form-control" required placeholder="যেমন: মিরপুর - মাদ্রাসা" /></div><div class="form-group"><label>শুরু</label><input v-model="form.start_point" class="form-control" /></div><div class="form-group"><label>গন্তব্য</label><input v-model="form.end_point" class="form-control" /></div><div class="form-group"><label>দূরত্ব (কিমি)</label><input v-model.number="form.distance_km" type="number" step=".1" class="form-control" /></div><div class="form-group"><label>ভাড়া</label><input v-model.number="form.fare" type="number" class="form-control" /></div></div><div class="form-actions"><button class="btn btn-primary" :disabled="saving">{{ saving?'সংরক্ষণ হচ্ছে...':'রুট তৈরি করুন' }}</button><button type="button" class="btn btn-ghost" @click="showForm=false">বাতিল</button></div></form><div v-if="loading" class="loading-state"><div class="spinner" /></div><div v-else-if="!routes.length" class="empty-card"><div class="empty-icon"><icon name="bus" /></div><h3>কোনো পরিবহন রুট নেই</h3><p>শিক্ষার্থীদের যাতায়াত সংগঠিত করতে প্রথম রুটটি যোগ করুন</p></div><div v-else class="route-grid"><article v-for="route in routes" :key="route.id" class="route-card"><div class="route-top"><span class="route-icon"><icon name="bus" /></span><span class="status" :class="route.is_active?'active':'inactive'">{{ route.is_active?'সক্রিয়':'নিষ্ক্রিয়' }}</span></div><h3>{{ route.route_name_bn || route.route_name_en }}</h3><div class="route-path"><span>{{ route.start_point || 'শুরু নির্ধারিত নয়' }}</span><i /> <span>{{ route.end_point || 'গন্তব্য নির্ধারিত নয়' }}</span></div><div class="route-meta"><span>{{ route.distance_km || 0 }} কিমি</span><span>৳{{ Number(route.fare||0).toLocaleString('bn-BD') }}</span><span>{{ route.buses?.length || 0 }} বাস</span></div></article></div></div>
</template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{useApiClient}from'~/utils/api';const api=useApiClient();const routes=ref<any[]>([]);const loading=ref(true);const saving=ref(false);const showForm=ref(false);const error=ref('');const search=ref('');const form=reactive({route_name_bn:'',start_point:'',end_point:'',distance_km:0,fare:0});async function load(){loading.value=true;try{const q=search.value?`?search=${encodeURIComponent(search.value)}`:'';const r=await api.get(`/transport/routes${q}`);routes.value=r.data?.data?.data||r.data?.data||[]}catch(e){console.error(e)}finally{loading.value=false}}async function createRoute(){saving.value=true;error.value='';try{await api.post('/transport/routes',form);showForm.value=false;form.route_name_bn='';form.start_point='';form.end_point='';await load()}catch(e:any){error.value=e?.response?.data?.message||'রুট তৈরি করা যায়নি'}finally{saving.value=false}}onMounted(load)</script>
<style scoped>.module-page{max-width:1400px;margin:0 auto;padding-bottom:2rem}.page-header-row{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin-bottom:1.4rem}.eyebrow{color:var(--color-primary);font:600 .78rem var(--font-bn)}.page-header-row h1{margin:.25rem 0;color:var(--color-primary);font:700 1.65rem var(--font-bn)}.page-header-row p{color:var(--color-text-light);font:.88rem var(--font-bn)}.toolbar{display:flex;gap:.7rem;padding:.7rem;margin-bottom:1rem}.search-box{display:flex;align-items:center;gap:.5rem;flex:1;padding:0 .75rem;background:var(--color-bg-muted);border-radius:10px}.search-box input{width:100%;padding:.65rem 0;border:0;outline:0;background:transparent;font:.86rem var(--font-bn)}.create-panel{padding:1.2rem;margin-bottom:1rem}.form-heading{display:flex;justify-content:space-between;margin-bottom:1rem}.form-heading h2{font:700 1rem var(--font-bn)}.close-btn{border:0;background:transparent;font-size:1.5rem;color:var(--color-text-muted);cursor:pointer}.form-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:.7rem}.form-group.wide{grid-column:span 2}.form-group label{display:block;margin-bottom:.3rem;font:600 .78rem var(--font-bn)}.form-actions{display:flex;gap:.6rem;margin-top:1rem}.route-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.route-card{padding:1.1rem;background:#fff;border:1px solid var(--color-border-light);border-radius:17px;box-shadow:var(--shadow-sm);transition:.2s}.route-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-md)}.route-top{display:flex;justify-content:space-between;align-items:center}.route-icon{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;color:#2c719c;background:#e3f2fa}.status{padding:.24rem .6rem;border-radius:99px;font:.7rem var(--font-bn)}.status.active{color:#19724a;background:#e6f4ec}.status.inactive{color:#a05c35;background:#fff0e4}.route-card h3{margin:1rem 0;color:var(--color-text);font:700 1rem var(--font-bn)}.route-path{display:grid;grid-template-columns:1fr 22px 1fr;align-items:center;gap:.45rem;color:var(--color-text-light);font:.75rem var(--font-bn)}.route-path i{height:2px;background:var(--color-accent)}.route-meta{display:flex;justify-content:space-between;padding-top:.9rem;margin-top:1rem;border-top:1px solid var(--color-border-light);color:var(--color-text-muted);font:.72rem var(--font-bn)}.empty-card{padding:3rem;text-align:center;background:#fff;border:1px dashed var(--color-border);border-radius:18px}.empty-icon{display:grid;place-items:center;width:54px;height:54px;margin:0 auto 1rem;border-radius:16px;color:#2c719c;background:#e3f2fa;font-size:1.4rem}.empty-card h3{font:700 1rem var(--font-bn)}.empty-card p{color:var(--color-text-light);font:.8rem var(--font-bn)}@media(max-width:950px){.route-grid{grid-template-columns:repeat(2,1fr)}.form-grid{grid-template-columns:repeat(3,1fr)}.form-group.wide{grid-column:span 2}}@media(max-width:650px){.page-header-row{align-items:flex-start;flex-direction:column}.toolbar{flex-wrap:wrap}.search-box{min-width:100%}.route-grid,.form-grid{grid-template-columns:1fr}.form-group.wide{grid-column:auto}}
</style>
